type LoginPM struct {
    Email    string
    Busy     bool
    onChange func()
}

func (m *LoginPM) SubmitEnabled() bool { return m.Email != "" && !m.Busy } // decision
func (m *LoginPM) Submit()             { m.Busy = true; m.onChange() }     // command

